    'bank_of_springfield': 'US',
    'dagoberts_vault': 'NL',
    'dagoberts_geldpakhuis': 'NL',
    'lehman_brothers': 'US',
    'medici': 'IT',
    'tellsons_bank': 'FR'
}

# Belles acquirer country
belles_acquirer_country = acquirer_country[belles['acquirer'][0]]  # US

