        if row['merchant'] == 'Belles_cookbook_store' and row['year'] == '2023':
            day = int(row['day_of_year'])
            amount = float(row['eur_amount'])
            is_fraud = row['has_fraudulent_dispute'] == 'True'

            if 1 <= day <= 31:
                monthly_volume += amount
                if is_fraud:
                    monthly_fraud_volume += amount

            if day == 10:
                daily_transactions.append(row)

monthly_fraud_level = monthly_fraud_volume / monthly_volume * 100 if monthly_volume > 0 else 0

print(f"Monthly volume: {monthly_volume:.2f} (range: 100k-1m)")
print(f"Monthly fraud level: {monthly_fraud_level:.2f}% (range: >8.3%)")

def parse_volume_range(vol_str):
    """Parse volume range string like '100k-1m' into (min, max) in euros."""
    if vol_str is None:
        return None, None
    parts = vol_str.split('-')
    def parse_val(s):
        s = s.strip()
        if s.endswith('k'):
            return float(s[:-1]) * 1000
        elif s.endswith('m'):
            return float(s[:-1]) * 1000000
        else:
            return float(s)
    return parse_val(parts[0]), parse_val(parts[1])

def matches_volume(merchant_volume, vol_rule):
    if vol_rule is None:
        return True
    lo, hi = parse_volume_range(vol_rule)
    if lo is not None and hi is not None:
        return lo <= merchant_volume <= hi
    return False

def parse_fraud_range(fraud_str):
    """Parse fraud range like '7.7%-8.3%' into (min, max) percentages."""
    if fraud_str is None:
        return None, None
    if fraud_str.startswith('>'):
        return float(fraud_str[1:].rstrip('%')), float('inf')
    if fraud_str.startswith('<'):
        return 0, float(fraud_str[1:].rstrip('%'))
    parts = fraud_str.split('-')
    return float(parts[0].rstrip('%')), float(parts[1].rstrip('%'))

def matches_fraud(merchant_fraud, fraud_rule):
    if fraud_rule is None:
        return True
    lo, hi = parse_fraud_range(fraud_rule)
    if lo is not None and hi is not None:
        return lo <= merchant_fraud <= hi
    return False

def matches_capture_delay(merchant_delay, rule_delay):
    """Merchant capture_delay is a string like '1', '7', 'immediate', 'manual'.
    Rule capture_delay is like '3-5', '>5', '<3', 'immediate', 'manual', or null."""
    if rule_delay is None:
        return True

    md = merchant_delay

    # Try to parse merchant delay as integer
    try:
        md_int = int(md)
    except ValueError:
        md_int = None

    if rule_delay == 'immediate':
        return md == 'immediate'
    elif rule_delay == 'manual':
        return md == 'manual'
    elif rule_delay.startswith('>'):
        if md_int is None:
            return False
        threshold = int(rule_delay[1:])
        return md_int > threshold
    elif rule_delay.startswith('<'):
        if md_int is None:
            return False
        threshold = int(rule_delay[1:])
        return md_int < threshold
    elif '-' in rule_delay:
        if md_int is None:
            return False
        parts = rule_delay.split('-')
        lo, hi = int(parts[0]), int(parts[1])
        return lo <= md_int <= hi
    else:
        # Exact match?
        return md == rule_delay

# Now match each fee rule to each transaction
applicable_fee_ids = set()

for fee in fees:
    # Check merchant-level matching first
    # account_type: must include "R" or be empty/null
    fee_account_types = fee.get('account_type')
    if fee_account_types is not None and len(fee_account_types) > 0:
        if belles['account_type'] not in fee_account_types:
            continue

