        continue

    # merchant_category_code: must include 5942 or be empty/null
    fee_mcc = fee.get('merchant_category_code')
    if fee_mcc is not None and len(fee_mcc) > 0:
        if belles['merchant_category_code'] not in fee_mcc:
            continue

    # Now check each transaction
    for txn in daily_transactions:
        # card_scheme
        fee_scheme = fee.get('card_scheme')
        if fee_scheme is not None and fee_scheme != txn['card_scheme']:
            continue

        # is_credit
        fee_is_credit = fee.get('is_credit')
        if fee_is_credit is not None:
            txn_is_credit = txn['is_credit'] == 'True'
            if fee_is_credit != txn_is_credit:
                continue

        # aci
        fee_aci = fee.get('aci')
        if fee_aci is not None and len(fee_aci) > 0:
            if txn['aci'] not in fee_aci:
                continue

        # intracountry
        fee_intracountry = fee.get('intracountry')
        if fee_intracountry is not None:
            txn_intracountry = (txn['issuing_country'] == txn['acquirer_country'])
            if fee_intracountry != txn_intracountry:
                continue

        # All matched!
        applicable_fee_ids.add(fee['ID'])

print(f"\nApplicable fee IDs: {sorted(applicable_fee_ids)}")
print(f"Count: {len(applicable_fee_ids)}")

# Write answer
answer = ', '.join(str(fid) for fid in sorted(applicable_fee_ids))
with open('answers.json', 'w') as f:
    json.dump({"answer": [answer]}, f)
print(f"\nAnswer: {answer}")

